import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { motion } from 'motion/react';
import {
  ArrowRight,
  Compass,
  Home,
  Library,
  Loader2,
  LockKeyhole,
  LogIn,
  MessageCircleMore,
  Plus,
  Search,
  ShieldCheck,
  Sparkles,
  Users,
} from 'lucide-react';
import { useNavigate, useParams, useSearchParams } from 'react-router-dom';
import type { User } from '@supabase/supabase-js';
import { CommunityView as WorkspaceCommunityView } from '../components/workspace/CommunityView';
import { WorkspaceCreateCommunityWizard } from '../components/workspace/WorkspaceCreateCommunityWizard';
import { supabase } from '../lib/supabase';

type CommunitySummary = {
  id: string;
  owner_id: string;
  name: string;
  description: string | null;
  logo_url: string | null;
  banner_url: string | null;
  is_private: boolean | null;
  privacy_level: string | null;
  price: number | null;
  created_at: string;
  member_count: number | null;
  paid: boolean | null;
};

type CommunityRow = Omit<CommunitySummary, 'member_count' | 'paid'>;

const COMMUNITY_FIELDS = 'id, owner_id, name, description, logo_url, banner_url, is_private, privacy_level, price, created_at';

const communityPath = (communityId: string) => `/community/${encodeURIComponent(communityId)}`;

const CommunityMark = ({ community, size = 'md' }: { community: Pick<CommunitySummary, 'name' | 'logo_url'>; size?: 'sm' | 'md' | 'lg' }) => {
  const sizeClass = size === 'lg' ? 'h-16 w-16 rounded-[22px] text-xl' : size === 'sm' ? 'h-10 w-10 rounded-[14px] text-xs' : 'h-12 w-12 rounded-[17px] text-sm';
  return (
    <span className={`grid shrink-0 place-items-center overflow-hidden bg-gradient-to-br from-indigo-500 to-violet-700 font-black text-white shadow-lg shadow-black/20 ${sizeClass}`}>
      {community.logo_url
        ? <img src={community.logo_url} alt="" className="h-full w-full object-cover" referrerPolicy="no-referrer" />
        : community.name.slice(0, 1).toUpperCase()}
    </span>
  );
};

const CommunityCard = ({ community, owned, onOpen }: { community: CommunitySummary; owned: boolean; onOpen: () => void }) => (
  <motion.button
    type="button"
    whileHover={{ y: -3 }}
    whileTap={{ scale: 0.985 }}
    onClick={onOpen}
    className="group overflow-hidden rounded-[30px] border border-white/[0.08] bg-[#111113] text-left shadow-[0_20px_60px_rgba(0,0,0,0.22)] transition hover:border-white/15"
  >
    <div className="relative h-32 overflow-hidden bg-[radial-gradient(circle_at_20%_0%,rgba(99,102,241,.48),transparent_52%),radial-gradient(circle_at_90%_100%,rgba(16,185,129,.22),transparent_50%),#17171a]">
      {community.banner_url && <img src={community.banner_url} alt="" className="h-full w-full object-cover opacity-75 transition duration-500 group-hover:scale-[1.03]" referrerPolicy="no-referrer" />}
      <div className="absolute inset-0 bg-gradient-to-t from-[#111113] via-transparent to-black/10" />
      <div className="absolute bottom-4 left-5"><CommunityMark community={community} size="lg" /></div>
      <div className="absolute right-4 top-4 flex gap-2">
        {owned && <span className="grid h-9 w-9 place-items-center rounded-full border border-white/10 bg-black/45 text-indigo-200 backdrop-blur-xl" title="You own this community"><ShieldCheck className="h-4 w-4" /></span>}
        {community.is_private || community.privacy_level === 'private' ? <span className="grid h-9 w-9 place-items-center rounded-full border border-white/10 bg-black/45 text-white/65 backdrop-blur-xl"><LockKeyhole className="h-4 w-4" /></span> : null}
      </div>
    </div>
    <div className="p-5">
      <div className="flex items-start gap-3">
        <div className="min-w-0 flex-1">
          <h2 className="truncate text-lg font-black tracking-tight text-white">{community.name}</h2>
          <p className="mt-2 line-clamp-2 min-h-10 text-sm leading-5 text-white/42">{community.description || 'A community on Wersee.'}</p>
        </div>
        <span className="grid h-10 w-10 shrink-0 place-items-center rounded-full border border-white/[0.08] bg-white/[0.04] text-white/35 transition group-hover:bg-white group-hover:text-black"><ArrowRight className="h-4 w-4" /></span>
      </div>
      <div className="mt-5 flex items-center gap-2 border-t border-white/[0.06] pt-4 text-[11px] font-bold text-white/38">
        <span className="inline-flex items-center gap-1.5"><Users className="h-3.5 w-3.5" />{community.member_count === null ? 'Members unavailable' : `${community.member_count.toLocaleString()} members`}</span>
        {community.paid || Number(community.price || 0) > 0
          ? <span className="ml-auto rounded-full border border-violet-300/15 bg-violet-400/10 px-2.5 py-1 text-violet-200">Paid</span>
          : community.paid === false
            ? <span className="ml-auto rounded-full border border-emerald-300/15 bg-emerald-400/10 px-2.5 py-1 text-emerald-200">Free</span>
            : <span className="ml-auto rounded-full border border-white/10 bg-white/[0.04] px-2.5 py-1 text-white/45">Access details</span>}
      </div>
    </div>
  </motion.button>
);

export const CommunityView = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [myCommunities, setMyCommunities] = useState<CommunitySummary[]>([]);
  const [libraryCommunities, setLibraryCommunities] = useState<CommunitySummary[]>([]);
  const [loadingCommunities, setLoadingCommunities] = useState(true);
  const [communityError, setCommunityError] = useState('');
  const [query, setQuery] = useState('');
  const surface = searchParams.get('view');
  const showingLibrary = surface === 'library';
  const showingCreate = surface === 'create';

  useEffect(() => {
    let active = true;
    void supabase.auth.getUser().then(({ data }) => {
      if (!active) return;
      setUser(data.user || null);
      setAuthLoading(false);
    });
    const { data: authListener } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user || null);
      setAuthLoading(false);
    });
    return () => {
      active = false;
      authListener.subscription.unsubscribe();
    };
  }, []);

  const enrichCommunities = useCallback(async (rows: CommunityRow[]) => {
    const ids = rows.map((community) => community.id);
    if (ids.length === 0) return [];
    const [membershipResult, tierResult] = await Promise.all([
      supabase.from('community_members').select('community_id').in('community_id', ids),
      supabase.from('community_monetization_tiers').select('community_id').in('community_id', ids).eq('is_active', true).is('archived_at', null),
    ]);
    const counts = new Map<string, number>();
    (membershipResult.data || []).forEach((membership) => counts.set(membership.community_id, (counts.get(membership.community_id) || 0) + 1));
    const paidIds = new Set((tierResult.data || []).map((tier) => tier.community_id));
    return rows.map((community) => ({
      ...community,
      member_count: membershipResult.error ? null : (counts.get(community.id) || 0),
      paid: tierResult.error ? (Number(community.price || 0) > 0 ? true : null) : paidIds.has(community.id),
    }));
  }, []);

  const loadCommunities = useCallback(async () => {
    setLoadingCommunities(true);
    setCommunityError('');
    try {
      const publicRequest = supabase
        .from('communities')
        .select(COMMUNITY_FIELDS)
        .eq('is_private', false)
        .order('created_at', { ascending: false })
        .limit(60);

      let personalRows: CommunityRow[] = [];
      if (user?.id) {
        const [{ data: memberships, error: membershipError }, { data: owned, error: ownedError }] = await Promise.all([
          supabase.from('community_members').select('community_id').eq('user_id', user.id),
          supabase.from('communities').select(COMMUNITY_FIELDS).eq('owner_id', user.id),
        ]);
        if (membershipError) throw membershipError;
        if (ownedError) throw ownedError;
        const ids = Array.from(new Set([...(memberships || []).map((membership) => membership.community_id), ...(owned || []).map((community) => community.id)]));
        if (ids.length > 0) {
          const { data, error } = await supabase.from('communities').select(COMMUNITY_FIELDS).in('id', ids);
          if (error) throw error;
          personalRows = (data || []) as CommunityRow[];
        }
      }

      const { data: publicRows, error: publicError } = await publicRequest;
      if (publicError) throw publicError;
      const [personal, library] = await Promise.all([
        enrichCommunities(personalRows),
        enrichCommunities((publicRows || []) as CommunityRow[]),
      ]);
      setMyCommunities(personal.sort((left, right) => left.name.localeCompare(right.name)));
      setLibraryCommunities(library);
    } catch (error) {
      console.error('Community portal could not load communities:', error);
      setCommunityError('Communities are temporarily unavailable. Try again in a moment.');
    } finally {
      setLoadingCommunities(false);
    }
  }, [enrichCommunities, user?.id]);

  useEffect(() => {
    if (authLoading) return;
    void loadCommunities();
  }, [authLoading, loadCommunities]);

  useEffect(() => {
    if (!user?.id) return;
    const changes = supabase
      .channel(`community-portal:${user.id}`)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'community_members', filter: `user_id=eq.${user.id}` }, () => void loadCommunities())
      .on('postgres_changes', { event: '*', schema: 'public', table: 'communities' }, () => void loadCommunities())
      .subscribe();
    return () => { void supabase.removeChannel(changes); };
  }, [loadCommunities, user?.id]);

  const openSurface = (view?: 'library' | 'create') => {
    if (!view) {
      navigate('/community');
      return;
    }
    setSearchParams({ view });
  };

  const filteredCommunities = useMemo(() => {
    const source = showingLibrary ? libraryCommunities : myCommunities;
    const normalizedQuery = query.trim().toLowerCase();
    if (!normalizedQuery) return source;
    return source.filter((community) => community.name.toLowerCase().includes(normalizedQuery) || community.description?.toLowerCase().includes(normalizedQuery));
  }, [libraryCommunities, myCommunities, query, showingLibrary]);

  const showPortalChrome = Boolean(user) && !authLoading;

  if (authLoading) {
    return <main className="grid h-[100dvh] place-items-center bg-[#070708] text-white"><Loader2 className="h-6 w-6 animate-spin text-white/45" /></main>;
  }

  if (!showPortalChrome && id) {
    return <main className="h-[100dvh] min-h-0 overflow-hidden bg-[#080809]"><WorkspaceCommunityView communityId={id} /></main>;
  }

  if (!showPortalChrome && showingLibrary) {
    return (
      <main className="min-h-[100dvh] bg-[#070708] px-4 py-6 text-white sm:px-8 sm:py-9">
        <div className="mx-auto max-w-6xl">
          <header className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end">
            <div><p className="text-[10px] font-black uppercase tracking-[0.22em] text-indigo-300">Discover</p><h1 className="mt-2 text-4xl font-black tracking-[-0.045em] sm:text-5xl">Community library</h1><p className="mt-3 max-w-xl text-sm leading-6 text-white/42">Browse real public communities and open the space that fits you.</p></div>
            <div className="flex gap-2"><button type="button" onClick={() => setSearchParams({})} className="min-h-12 rounded-full border border-white/10 bg-white/[0.04] px-5 text-sm font-bold">Back</button><button type="button" onClick={() => navigate(`/auth?returnUrl=${encodeURIComponent('/community?view=create')}`)} className="min-h-12 rounded-full bg-white px-5 text-sm font-black text-black">Sign in or create</button></div>
          </header>
          <div className="relative mt-8"><Search className="absolute left-5 top-1/2 h-4 w-4 -translate-y-1/2 text-white/25" /><input type="search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search the community library" className="h-14 w-full rounded-full border border-white/[0.08] bg-white/[0.04] pl-12 pr-5 text-sm text-white outline-none placeholder:text-white/25 focus:border-indigo-300/35" /></div>
          {communityError ? <div role="alert" className="mt-8 rounded-[28px] border border-rose-400/15 bg-rose-400/[0.06] p-6 text-sm text-rose-100">{communityError}</div> : loadingCommunities ? <div className="mt-8 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{[1, 2, 3, 4, 5, 6].map((item) => <div key={item} className="h-[310px] animate-pulse rounded-[30px] bg-white/[0.04]" />)}</div> : filteredCommunities.length > 0 ? <div className="mt-8 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{filteredCommunities.map((community) => <CommunityCard key={community.id} community={community} owned={false} onOpen={() => navigate(communityPath(community.id))} />)}</div> : <div className="mt-8 rounded-[34px] border border-dashed border-white/10 px-6 py-16 text-center text-sm text-white/40">No public communities are currently available.</div>}
        </div>
      </main>
    );
  }

  if (!showPortalChrome) {
    return (
      <main className="relative min-h-[100dvh] overflow-hidden bg-[#070708] px-5 text-white">
        <div className="pointer-events-none absolute -left-40 -top-56 h-[620px] w-[620px] rounded-full bg-indigo-500/20 blur-[150px]" />
        <div className="pointer-events-none absolute -bottom-72 right-0 h-[620px] w-[620px] rounded-full bg-emerald-500/10 blur-[170px]" />
        <header className="relative z-10 mx-auto flex max-w-7xl items-center justify-between py-6">
          <div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-[14px] bg-white font-black text-black">W</span><div><p className="text-sm font-black">Wersee Community</p><p className="text-[10px] text-white/35">Find your people</p></div></div>
          <button type="button" onClick={() => navigate(`/auth?returnUrl=${encodeURIComponent('/community')}`)} className="inline-flex min-h-11 items-center gap-2 rounded-full border border-white/10 bg-white/[0.05] px-5 text-sm font-bold transition hover:bg-white hover:text-black"><LogIn className="h-4 w-4" />Sign in</button>
        </header>
        <section className="relative z-10 mx-auto flex min-h-[calc(100dvh-88px)] max-w-5xl flex-col items-center justify-center pb-24 text-center">
          <span className="inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/[0.05] px-4 py-2 text-[11px] font-black uppercase tracking-[0.18em] text-indigo-200"><Sparkles className="h-3.5 w-3.5" />Communities, together</span>
          <h1 className="mt-8 max-w-4xl text-balance text-5xl font-black leading-[0.95] tracking-[-0.06em] sm:text-7xl lg:text-[88px]">Your people. Your rooms. One place.</h1>
          <p className="mt-7 max-w-2xl text-balance text-base leading-7 text-white/45 sm:text-xl">Join conversations, courses, live rooms and member-only spaces. Community on Wersee keeps everything close without the clutter.</p>
          <div className="mt-9 flex w-full max-w-sm flex-col gap-3 sm:max-w-none sm:flex-row sm:justify-center">
            <button type="button" onClick={() => navigate(`/auth?returnUrl=${encodeURIComponent('/community?view=create')}`)} className="inline-flex min-h-14 items-center justify-center gap-2 rounded-full bg-white px-7 text-sm font-black text-black"><Plus className="h-4 w-4" />Create a community</button>
            <button type="button" onClick={() => setSearchParams({ view: 'library' })} className="inline-flex min-h-14 items-center justify-center gap-2 rounded-full border border-white/10 bg-white/[0.05] px-7 text-sm font-bold"><Compass className="h-4 w-4" />Explore community library</button>
          </div>
        </section>
      </main>
    );
  }

  return (
    <main className="flex h-[100dvh] min-h-0 overflow-hidden bg-[#070708] text-white">
      <aside className="z-40 hidden h-full w-[84px] shrink-0 flex-col items-center border-r border-white/[0.07] bg-[#0c0c0e]/95 px-3 py-4 md:flex" aria-label="Your communities">
        <button type="button" onClick={() => openSurface()} className={`grid h-12 w-12 place-items-center rounded-[17px] transition ${!id && !surface ? 'bg-white text-black' : 'bg-white/[0.06] text-white/55 hover:bg-white/[0.1] hover:text-white'}`} aria-label="Community home"><Home className="h-5 w-5" /></button>
        <div className="my-3 h-px w-8 bg-white/[0.08]" />
        <div className="min-h-0 flex-1 space-y-2 overflow-y-auto px-1 scrollbar-hide">
          {myCommunities.map((community) => (
            <button key={community.id} type="button" onClick={() => navigate(communityPath(community.id))} className="group relative block" aria-label={`Open ${community.name}`} title={community.name}>
              {id === community.id && <span className="absolute -left-[13px] top-1/2 h-7 w-1 -translate-y-1/2 rounded-r-full bg-white" />}
              <span className={`block rounded-[18px] ring-2 ring-offset-2 ring-offset-[#0c0c0e] transition ${id === community.id ? 'ring-white/70' : 'ring-transparent group-hover:ring-white/20'}`}><CommunityMark community={community} /></span>
            </button>
          ))}
        </div>
        <div className="mt-3 space-y-2 border-t border-white/[0.07] pt-3">
          <button type="button" onClick={() => openSurface('create')} className={`grid h-12 w-12 place-items-center rounded-[17px] border transition ${showingCreate ? 'border-white bg-white text-black' : 'border-white/[0.08] bg-white/[0.04] text-emerald-300 hover:bg-emerald-400/15'}`} aria-label="Create community" title="Create community"><Plus className="h-5 w-5" /></button>
          <button type="button" onClick={() => openSurface('library')} className={`grid h-12 w-12 place-items-center rounded-[17px] border transition ${showingLibrary ? 'border-white bg-white text-black' : 'border-white/[0.08] bg-white/[0.04] text-indigo-200 hover:bg-indigo-400/15'}`} aria-label="Community library" title="Community library"><Library className="h-5 w-5" /></button>
        </div>
      </aside>

      <section className="min-w-0 flex-1 pb-[76px] md:pb-0">
        {id && !showingLibrary && !showingCreate ? (
          <WorkspaceCommunityView communityId={id} />
        ) : showingCreate ? (
          <div className="h-full overflow-y-auto px-4 py-3 sm:px-8"><WorkspaceCreateCommunityWizard onClose={(communityId) => communityId ? navigate(communityPath(communityId)) : openSurface()} /></div>
        ) : (
          <div className="h-full overflow-y-auto px-4 py-6 sm:px-8 sm:py-9 lg:px-12">
            <div className="mx-auto max-w-6xl">
              <header className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end">
                <div>
                  <p className="text-[10px] font-black uppercase tracking-[0.22em] text-indigo-300">{showingLibrary ? 'Discover' : 'Community home'}</p>
                  <h1 className="mt-2 text-4xl font-black tracking-[-0.045em] sm:text-5xl">{showingLibrary ? 'Community library' : 'Your communities'}</h1>
                  <p className="mt-3 max-w-xl text-sm leading-6 text-white/42">{showingLibrary ? 'Browse public communities, from open conversations to premium member spaces.' : 'Jump back into every community you own or take part in.'}</p>
                </div>
                <button type="button" onClick={() => openSurface('create')} className="inline-flex min-h-12 items-center justify-center gap-2 rounded-full bg-white px-5 text-sm font-black text-black"><Plus className="h-4 w-4" />Create community</button>
              </header>

              <div className="relative mt-8">
                <Search className="absolute left-5 top-1/2 h-4 w-4 -translate-y-1/2 text-white/25" />
                <input type="search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder={showingLibrary ? 'Search the community library' : 'Search your communities'} className="h-14 w-full rounded-full border border-white/[0.08] bg-white/[0.04] pl-12 pr-5 text-sm text-white outline-none transition placeholder:text-white/25 focus:border-indigo-300/35 focus:bg-white/[0.06]" />
              </div>

              {communityError ? (
                <div role="alert" className="mt-8 rounded-[28px] border border-rose-400/15 bg-rose-400/[0.06] p-6 text-sm text-rose-100">{communityError}<button type="button" onClick={() => void loadCommunities()} className="ml-3 font-black underline underline-offset-4">Retry</button></div>
              ) : loadingCommunities ? (
                <div className="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{[1, 2, 3, 4, 5, 6].map((item) => <div key={item} className="h-[310px] animate-pulse rounded-[30px] bg-white/[0.04]" />)}</div>
              ) : filteredCommunities.length > 0 ? (
                <div className="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{filteredCommunities.map((community) => <CommunityCard key={community.id} community={community} owned={community.owner_id === user?.id} onOpen={() => navigate(communityPath(community.id))} />)}</div>
              ) : (
                <div className="mt-8 rounded-[34px] border border-dashed border-white/10 bg-white/[0.025] px-6 py-16 text-center">
                  <span className="mx-auto grid h-16 w-16 place-items-center rounded-[22px] bg-indigo-400/10 text-indigo-200"><MessageCircleMore className="h-7 w-7" /></span>
                  <h2 className="mt-5 text-xl font-black">{query ? 'No communities found' : showingLibrary ? 'The library is quiet right now' : 'Your first community starts here'}</h2>
                  <p className="mx-auto mt-2 max-w-md text-sm leading-6 text-white/40">{query ? 'Try another name or keyword.' : showingLibrary ? 'No public communities are currently available.' : 'Create your own space or open the library to discover an existing one.'}</p>
                  {!query && <div className="mt-6 flex flex-col justify-center gap-3 sm:flex-row"><button type="button" onClick={() => openSurface('create')} className="rounded-full bg-white px-5 py-3 text-sm font-black text-black">Create community</button>{!showingLibrary && <button type="button" onClick={() => openSurface('library')} className="rounded-full border border-white/10 bg-white/[0.04] px-5 py-3 text-sm font-bold">Open library</button>}</div>}
                </div>
              )}
            </div>
          </div>
        )}
      </section>

      <nav className="fixed inset-x-3 bottom-[max(10px,env(safe-area-inset-bottom))] z-50 flex h-16 items-center gap-2 overflow-x-auto rounded-[24px] border border-white/10 bg-[#101012]/95 px-2.5 shadow-[0_22px_70px_rgba(0,0,0,0.6)] backdrop-blur-2xl md:hidden" aria-label="Your communities">
        <button type="button" onClick={() => openSurface()} className={`grid h-11 w-11 shrink-0 place-items-center rounded-[15px] ${!id && !surface ? 'bg-white text-black' : 'bg-white/[0.05] text-white/55'}`} aria-label="Community home"><Home className="h-4 w-4" /></button>
        <span className="h-7 w-px shrink-0 bg-white/[0.08]" />
        {myCommunities.map((community) => <button key={community.id} type="button" onClick={() => navigate(communityPath(community.id))} className={`shrink-0 rounded-[15px] ring-2 ring-offset-1 ring-offset-[#101012] ${id === community.id ? 'ring-white/70' : 'ring-transparent'}`} aria-label={`Open ${community.name}`}><CommunityMark community={community} size="sm" /></button>)}
        <span className="ml-auto h-7 w-px shrink-0 bg-white/[0.08]" />
        <button type="button" onClick={() => openSurface('create')} className={`grid h-11 w-11 shrink-0 place-items-center rounded-[15px] ${showingCreate ? 'bg-white text-black' : 'bg-emerald-400/10 text-emerald-200'}`} aria-label="Create community"><Plus className="h-4 w-4" /></button>
        <button type="button" onClick={() => openSurface('library')} className={`grid h-11 w-11 shrink-0 place-items-center rounded-[15px] ${showingLibrary ? 'bg-white text-black' : 'bg-indigo-400/10 text-indigo-200'}`} aria-label="Community library"><Library className="h-4 w-4" /></button>
      </nav>
    </main>
  );
};
